    func narrow(query: String, sort: EngineSort) throws  -> UInt64
    
    func refresh(query: String, sort: EngineSort) throws  -> UInt64
    
    func rows(generation: UInt64, start: UInt32, count: UInt32) throws  -> [EngineHit]
    
    func search(query: String, sort: EngineSort) throws  -> UInt64
    
    func searchContent(query: String, terms: [String], matchAll: Bool, sort: EngineSort) throws  -> UInt64
    
    func sort(sort: EngineSort) throws  -> UInt64
    
    func stopContent() throws 
    
}
open class EngineSession: EngineSessionProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_wherever_core_fn_clone_enginesession(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_wherever_core_fn_free_enginesession(handle, $0) }
    }

    

    
open func id()throws  -> UInt64  {
    return try  FfiConverterUInt64.lift(try rustCallWithError(FfiConverterTypeEngineError_lift) {
        uniffiCallStatus in
    uniffi_wherever_core_fn_method_enginesession_id(
            self.uniffiCloneHandle(),uniffiCallStatus
    )
})
}
    
open func narrow(query: String, sort: EngineSort)throws  -> UInt64  {
    return try  FfiConverterUInt64.lift(try rustCallWithError(FfiConverterTypeEngineError_lift) {
        uniffiCallStatus in
    uniffi_wherever_core_fn_method_enginesession_narrow(
            self.uniffiCloneHandle(),
        FfiConverterString.lower(query),
        FfiConverterTypeEngineSort_lower(sort),uniffiCallStatus
