public struct FfiConverterTypeEngineSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = EngineSession

    public static func lift(_ handle: UInt64) throws -> EngineSession {
        return EngineSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: EngineSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EngineSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: EngineSession, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


